class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  version "0.2.0"
  license "Apache-2.0"

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.2.0/commando_0.2.0_darwin_arm64.tar.gz"
      sha256 "fd913501f67aa2b5855bdc06d262ff15824e11e95547b46886fa73f0b39fcf92"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.2.0/commando_0.2.0_darwin_amd64.tar.gz"
      sha256 "93251e0aef160e4c74f9ffe3aec1b42738965accdcb89af91811a53f88d20528"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.2.0/commando_0.2.0_linux_arm64.tar.gz"
      sha256 "4db05bd18fe8c724c10d7e847771feb430e4ada4a5afdf6d89ac695699a3b7f8"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.2.0/commando_0.2.0_linux_amd64.tar.gz"
      sha256 "ca3a52c4bf0f3ea401a850dcd58fe73ef3c68ddbf828649a2cd5b96ed66301d3"
    end
  end

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
